#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ========== НАСТРОЙКИ ==========
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_ADDR 0x3C          // Адрес OLED (0x3C или 0x3D)

#define GEIGER_PIN 2            // Выход счетчика Гейгера (прерывание)
#define BUZZER_PIN 3            // Пин зуммера
#define LED_PIN 4               // Встроенный светодиод (опционально)

// Коэффициент пересчета для вашей трубки (СБМ-20 = 0.0057)
#define CONV_FACTOR 0.0057      // мкЗв/ч на 1 CPM

// Порог звуковой тревоги (мкЗв/ч)
#define ALARM_THRESHOLD 0.30

// ========== ПЕРЕМЕННЫЕ ==========
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

volatile unsigned long pulseCount = 0;
unsigned long lastMeasureTime = 0;
unsigned long lastDisplayTime = 0;

float doseRate = 0.0;           // Текущая мощность дозы (мкЗв/ч)
float totalDose = 0.0;          // Накопленная доза (мкЗв)
float cpm = 0.0;               // Импульсов в минуту

bool alarmActive = false;

// ========== SETUP ==========
void setup() {
  Serial.begin(115200);

  // Инициализация OLED
  if(!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("Ошибка OLED!");
    while(true);
  }
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 20);
  display.println("Dosimeter v2.0");
  display.display();
  delay(1500);

  // Настройка пинов
  pinMode(GEIGER_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);

  // Прерывание по спадающему фронту (каждый импульс)
  attachInterrupt(digitalPinToInterrupt(GEIGER_PIN), pulseISR, FALLING);

  lastMeasureTime = millis();
  lastDisplayTime = millis();

  Serial.println("Дозиметр запущен!");
  display.clearDisplay();
}

// ========== LOOP ==========
void loop() {
  unsigned long currentTime = millis();

  // ===== 1. Измерение каждые 5 секунд =====
  if (currentTime - lastMeasureTime >= 5000) {
    noInterrupts();
    unsigned long count = pulseCount;
    pulseCount = 0;
    interrupts();

    // Расчет CPM (за 5 секунд -> умножаем на 12)
    cpm = (count / 5.0) * 60.0;

    // Мощность дозы в мкЗв/ч
    doseRate = cpm * CONV_FACTOR;

    // Накопленная доза (мкЗв) - прибавляем за 5 секунд
    totalDose += doseRate * (5.0 / 3600.0);

    // Логирование в Serial
    Serial.print("CPM: ");
    Serial.print(cpm, 0);
    Serial.print(" | Dose: ");
    Serial.print(doseRate, 3);
    Serial.println(" uSv/h");

    lastMeasureTime = currentTime;
  }

  // ===== 2. Обновление дисплея каждые 200 мс =====
  if (currentTime - lastDisplayTime >= 200) {
    updateDisplay();
    lastDisplayTime = currentTime;
  }

  // ===== 3. Звуковая тревога =====
  if (doseRate > ALARM_THRESHOLD) {
    if (!alarmActive) {
      alarmActive = true;
    }
    // Писк: 500 мс звук, 300 мс пауза
    static unsigned long lastBeep = 0;
    if (currentTime - lastBeep >= 800) {
      tone(BUZZER_PIN, 1200, 500);
      lastBeep = currentTime;
    }
  } else {
    if (alarmActive) {
      alarmActive = false;
      noTone(BUZZER_PIN);
    }
  }

  // ===== 4. Индикация импульсов (мигание светодиодом) =====
  static unsigned long lastBlink = 0;
  if (currentTime - lastBlink >= 50) {
    digitalWrite(LED_PIN, !digitalRead(LED_PIN));
    lastBlink = currentTime;
  }
}

// ========== ОБНОВЛЕНИЕ OLED ==========
void updateDisplay() {
  display.clearDisplay();

  // Верхняя строка: заголовок и статус тревоги
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("RAD");

  if (alarmActive) {
    display.setTextColor(SSD1306_WHITE, SSD1306_BLACK);
    display.print("  !!! ALARM !!!");
    display.setTextColor(SSD1306_WHITE);
  }

  // Мощность дозы (крупный шрифт)
  display.setTextSize(2);
  display.setCursor(0, 16);
  display.print(doseRate, 2);
  display.setTextSize(1);
  display.print(" uSv/h");

  // CPM и накопленная доза (мелкий шрифт)
  display.setTextSize(1);
  display.setCursor(0, 42);
  display.print("CPM:");
  display.print(cpm, 0);

  display.setCursor(0, 52);
  display.print("Total:");
  display.print(totalDose, 2);
  display.print(" uSv");

  display.display();
}

// ========== ОБРАБОТЧИК ПРЕРЫВАНИЙ ==========
void pulseISR() {
  pulseCount++;
}
